from pwn import *
import time
import random

def connect_server():
    return remote('misc.chal.csaw.io', 5000, timeout=5)

def extract_score(response):
    try:
        # Extract numeric score from response
        return int(''.join(filter(str.isdigit, response)))
    except:
        return None

def try_bases(conn, num_bases, bases_str):
    try:
        conn.sendline(str(num_bases).encode())
        conn.sendline(bases_str.encode())
        response = conn.recvline(timeout=5).decode().strip()
        print(f"Server response: {response}")
        if 'flag' in response.lower():
            return response
        return extract_score(response)
    except Exception as e:
        print(f"Error in try_bases: {e}")
        return None

def modify_bases(current, score, prev_score=None):
    # If we don't have a previous score, flip a random bit
    if prev_score is None:
        pos = random.randrange(len(current))
        new_bases = list(current)
        new_bases[pos] = '1' if new_bases[pos] == '0' else '0'
        return ''.join(new_bases)

    # If score improved, keep going in that direction
    if score > prev_score:
        pos = random.randrange(len(current))
        new_bases = list(current)
        new_bases[pos] = '1' if new_bases[pos] == '0' else '0'
        return ''.join(new_bases)

    # If score got worse, try a different strategy
    # Try flipping multiple bits
    new_bases = list(current)
    num_flips = random.randint(1, max(1, len(current) // 4))
    positions = random.sample(range(len(current)), num_flips)
    for pos in positions:
        new_bases[pos] = '1' if new_bases[pos] == '0' else '0'
    return ''.join(new_bases)

def solve_challenge():
    max_attempts = 50  # Maximum total attempts
    attempts = 0

    while attempts < max_attempts:
        try:
            conn = connect_server()
            print("\nConnected to server")

            # Try to get initial number of qubits
            initial_response = conn.recvline(timeout=5).decode().strip()
            print(f"Initial server message: {initial_response}")

            # Try different numbers of bases based on server response
            for num_bases in [8, 16, 32, 64]:
                print(f"\nTrying with {num_bases} bases")

                # Start with alternating bases
                current = ''.join(['0' if i % 2 == 0 else '1' for i in range(num_bases)])
                prev_score = None

                for attempt in range(15):  # More attempts per size
                    attempts += 1
                    print(f"\nAttempt {attempt + 1} with {num_bases} bases:")
                    print(f"Sending bases: {current}")

                    result = try_bases(conn, num_bases, current)

                    if isinstance(result, str) and 'flag' in result.lower():
                        conn.close()
                        return result

                    if result is not None:
                        print(f"Score: {result}")
                        new_bases = modify_bases(current, result, prev_score)
                        prev_score = result
                        current = new_bases
                    else:
                        print("Invalid response, retrying...")
                        break

            conn.close()
            time.sleep(1)  # Small delay between connection attempts

        except EOFError:
            print("Server closed connection, retrying...")
            time.sleep(2)
        except Exception as e:
            print(f"Connection error: {e}")
            time.sleep(2)

# Run solver
print("Starting QKD solver...")
result = solve_challenge()
print("\nFinal result:", result)
